import XCTest
@testable import SimulationCore

final class SimulationTests: XCTestCase {
    func testForwardReverseAndBrake() {
        var sim = Simulation(), input = DriveInput()
        let start = sim.z
        input.throttle = 1
        for _ in 0..<60 { sim.advance(input, dt: 1.0/60) }
        XCTAssertGreaterThan(sim.z, start+0.8)
        input.brake = true
        let z = sim.z
        sim.advance(input, dt: 1.0/60)
        XCTAssertEqual(sim.speed, 0)
        XCTAssertEqual(sim.z, z)
        input.brake = false; input.throttle = -1
        for _ in 0..<60 { sim.advance(input, dt: 1.0/60) }
        XCTAssertLessThan(sim.z, z-0.8)
    }
    func testTurningInPlace() {
        var sim = Simulation(), input = DriveInput()
        input.turn = 1
        for _ in 0..<30 { sim.advance(input, dt: 1.0/60) }
        XCTAssertGreaterThan(sim.heading, 0.5)
        XCTAssertEqual(sim.x, 0, accuracy: 1e-9)
        XCTAssertEqual(sim.z, -2.6, accuracy: 1e-9)
    }
    func testCollisionAndCheckpoint() {
        var sim = Simulation(), input = DriveInput()
        input.throttle = 1; input.boost = true
        for _ in 0..<600 { sim.advance(input, dt: 1.0/60) }
        XCTAssertTrue(sim.contacting)
        XCTAssertEqual(sim.checkpoint, 1)
        XCTAssertLessThan(sim.z, 3.3-0.65/2-Simulation.radius+0.01)
        XCTAssertTrue(Simulation.isFree(x: sim.x, z: sim.z))
        XCTAssertFalse(Simulation.isFree(x: 6, z: 0))
        XCTAssertFalse(Simulation.isFree(x: -2.2, z: -0.4))
    }
    func testPauseResetAndHeadLimits() {
        var sim = Simulation(), input = DriveInput()
        input.throttle = 1; input.headYaw = 1; input.headPitch = -1
        sim.paused = true
        sim.advance(input, dt: 1)
        XCTAssertEqual(sim.elapsed, 0)
        sim.paused = false
        for _ in 0..<300 { sim.advance(input, dt: 1.0/60) }
        XCTAssertEqual(sim.yaw, 80 * .pi/180, accuracy: 1e-9)
        XCTAssertEqual(sim.pitch, -45 * .pi/180, accuracy: 1e-9)
        sim.reset()
        XCTAssertEqual(sim.distance, 0)
        XCTAssertEqual(sim.yaw, 0)
        XCTAssertEqual(sim.z, -2.6)
    }
    func testFrameRateIndependentAndStallBounded() {
        var a = Simulation(), b = Simulation(), input = DriveInput()
        input.throttle = 1; input.turn = 0.2
        for _ in 0..<30 { a.advance(input, dt: 1.0/30) }
        for _ in 0..<120 { b.advance(input, dt: 1.0/120) }
        XCTAssertEqual(a.x, b.x, accuracy: 0.0001)
        XCTAssertEqual(a.z, b.z, accuracy: 0.0001)
        let elapsed = a.elapsed
        a.advance(input, dt: 30)
        XCTAssertEqual(a.elapsed-elapsed, 0.1, accuracy: 1e-9)
    }
}
